/* Spotify Theme - Official Spotify brand colors */

/* Light mode */
[data-theme="spotify-light"] {
  --background: rgb(255, 255, 255);
  --foreground: rgb(17, 12, 12);
  --card: rgb(250, 248, 248);
  --card-foreground: rgb(17, 12, 12);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(17, 12, 12);
  --primary: rgb(0, 168, 85);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(235, 240, 236);
  --secondary-foreground: rgb(26, 20, 20);
  --muted: rgb(244, 241, 242);
  --muted-foreground: rgb(104, 97, 99);
  --accent: rgb(0, 197, 91);
  --accent-foreground: rgb(17, 12, 12);
  --destructive: rgb(212, 9, 36);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(224, 221, 222);
  --input: rgb(230, 228, 228);
  --ring: rgb(0, 168, 85);
  --chart-1: rgb(0, 168, 85);
  --chart-2: rgb(0, 197, 91);
  --chart-3: rgb(0, 146, 152);
  --chart-4: rgb(144, 149, 232);
  --chart-5: rgb(211, 91, 177);
  --radius: 0.5rem;
  --sidebar: rgb(17, 12, 12);
  --sidebar-foreground: rgb(240, 238, 238);
  --sidebar-primary: rgb(0, 168, 85);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(38, 32, 31);
  --sidebar-accent-foreground: rgb(240, 238, 238);
  --sidebar-border: rgb(46, 39, 38);
  --sidebar-ring: rgb(0, 168, 85);
  --font-sans: Montserrat, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, monospace;
  --shadow-color: rgb(10, 41, 26);
  --shadow-opacity: 0.08;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(150 60% 10% / 0.04);
  --shadow-xs: 0 1px 3px 0px hsl(150 60% 10% / 0.06);
  --shadow-sm: 0 2px 4px 0px hsl(150 60% 10% / 0.08), 0 1px 2px -1px hsl(150 60% 10% / 0.08);
  --shadow: 0 2px 4px 0px hsl(150 60% 10% / 0.08), 0 1px 2px -1px hsl(150 60% 10% / 0.08);
  --shadow-md: 0 4px 6px 0px hsl(150 60% 10% / 0.1), 0 2px 4px -1px hsl(150 60% 10% / 0.1);
  --shadow-lg: 0 8px 10px 0px hsl(150 60% 10% / 0.1), 0 4px 6px -1px hsl(150 60% 10% / 0.1);
  --shadow-xl: 0 16px 20px 0px hsl(150 60% 10% / 0.12), 0 8px 10px -1px hsl(150 60% 10% / 0.12);
  --shadow-2xl: 0 24px 48px 0px hsl(150 60% 10% / 0.2);
  --tracking-normal: -0.01em;
}

/* Dark mode - #121212 is Spotify's signature dark background */
[data-theme="spotify-dark"] {
  --background: rgb(10, 10, 10);
  --foreground: rgb(255, 255, 255);
  --card: rgb(18, 18, 18);
  --card-foreground: rgb(255, 255, 255);
  --popover: rgb(22, 22, 22);
  --popover-foreground: rgb(255, 255, 255);
  --primary: rgb(0, 168, 85);
  --primary-foreground: rgb(10, 10, 10);
  --secondary: rgb(27, 27, 27);
  --secondary-foreground: rgb(222, 222, 222);
  --muted: rgb(22, 22, 22);
  --muted-foreground: rgb(143, 143, 143);
  --accent: rgb(0, 197, 91);
  --accent-foreground: rgb(10, 10, 10);
  --destructive: rgb(222, 59, 61);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(41, 41, 41);
  --input: rgb(27, 27, 27);
  --ring: rgb(0, 168, 85);
  --chart-1: rgb(0, 168, 85);
  --chart-2: rgb(0, 197, 91);
  --chart-3: rgb(0, 163, 170);
  --chart-4: rgb(159, 165, 249);
  --chart-5: rgb(222, 115, 189);
  --radius: 0.5rem;
  --sidebar: rgb(6, 6, 6);
  --sidebar-foreground: rgb(255, 255, 255);
  --sidebar-primary: rgb(0, 168, 85);
  --sidebar-primary-foreground: rgb(10, 10, 10);
  --sidebar-accent: rgb(27, 27, 27);
  --sidebar-accent-foreground: rgb(222, 222, 222);
  --sidebar-border: rgb(41, 41, 41);
  --sidebar-ring: rgb(0, 168, 85);
  --font-sans: Montserrat, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.5;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(0 0% 0% / 0.25);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.35);
  --shadow-sm: 0 2px 4px 0px hsl(0 0% 0% / 0.5), 0 1px 2px -1px hsl(0 0% 0% / 0.5);
  --shadow: 0 2px 4px 0px hsl(0 0% 0% / 0.5), 0 1px 2px -1px hsl(0 0% 0% / 0.5);
  --shadow-md: 0 4px 6px 0px hsl(0 0% 0% / 0.5), 0 2px 4px -1px hsl(0 0% 0% / 0.5);
  --shadow-lg: 0 8px 10px 0px hsl(0 0% 0% / 0.5), 0 4px 6px -1px hsl(0 0% 0% / 0.5);
  --shadow-xl: 0 16px 20px 0px hsl(0 0% 0% / 0.5), 0 8px 10px -1px hsl(0 0% 0% / 0.5);
  --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.6);
}
